def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return max(0.0, min(budget, 1.0))

    prev_bids = []
    threat_bids = []
    rich_threat = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid')
        if b is not None:
            prev_bids.append(float(b))
            if opp.get('budget', 0) >= DAILY_SALARY * 0.8:
                threat_bids.append(float(b))
        rich_threat = max(rich_threat, float(opp.get('budget', 0)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat_prev = max(threat_bids) if threat_bids else highest_prev

    tight_supply = supply <= 17
    very_tight = supply <= 16
    abundant = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1
    elif abundant:
        urgency -= 1

    if budget < DAILY_SALARY:
        urgency += 1
    if budget > 250:
        urgency -= 1

    if urgency <= 0:
        base = 8.0 if abundant else 12.0
        if highest_prev >= 100:
            bid = base
        elif highest_prev >= 80:
            bid = max(base, 18.0)
        else:
            bid = max(base, min(28.0, highest_prev * 0.55 + 3.0))
    elif urgency == 1:
        if highest_threat_prev >= 100:
            bid = 38.0 if not tight_supply else 52.0
        else:
            bid = max(26.0, min(60.0, highest_threat_prev + 2.0))
    elif urgency == 2:
        if highest_threat_prev >= 105:
            bid = 72.0
        else:
            bid = max(45.0, min(78.0, highest_threat_prev + 4.0))
    elif urgency == 3:
        if highest_threat_prev >= 110:
            bid = 88.0
        else:
            bid = max(62.0, min(92.0, highest_threat_prev + 6.0))
    else:
        if highest_threat_prev >= 110:
            bid = 108.0
        else:
            bid = max(85.0, min(118.0, highest_threat_prev + 8.0))

    if day >= 8 and hp >= 6 and no_water_days == 0 and highest_prev >= 90:
        bid = min(bid, 24.0)

    if budget <= 25:
        bid = min(bid, budget)
    else:
        reserve = 10.0 if day < 8 else 0.0
        bid = min(bid, max(0.0, budget - reserve))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, 95.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Determine how many full WATER_REQ units the supply can cover.
    # Use int() to satisfy index safety and avoid float artifacts.
    supply_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # If supply is low, competition is tighter; bid more.
    # If supply is high, bid less since winning is easier.
    if supply_units <= 1:
        pressure = 0.85
    elif supply_units == 2:
        pressure = 0.70
    else:
        pressure = 0.55

    alive_opponents = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opponents.append((oid, o))
        except Exception:
            continue

    # React to yesterday's bidding pressure.
    prev_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Base bid target: upper-mid of yesterday leaders.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        median_prev_bid = sorted(prev_bids)[len(prev_bids)//2]

        # Cindy died with avg ~66.9, so avoid going that low against active spenders.
        # If leaders bid near/above ~DAILY_SALARY, match slightly below to win efficiently.
        leader_cut = 0.92
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(median_prev_bid, highest_prev_bid * leader_cut)
        else:
            target = max(median_prev_bid, highest_prev_bid - 3.0)
    else:
        target = DAILY_SALARY * 0.55

    # Adjust by current HP: high HP can afford slightly lower bids.
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    if hp <= 2:
        hp_factor = 0.95
    elif hp <= 4:
        hp_factor = 0.85
    elif hp <= 6:
        hp_factor = 0.75
    else:
        hp_factor = 0.70

    # Pressure adjustment based on supply.
    target = target * (0.65 + 0.35 * pressure) * hp_factor

    # Ensure we don't bid more than budget and keep within a reasonable cap.
    # Cap near daily salary to avoid runaway spending.
    cap = min(budget, DAILY_SALARY * 0.95)

    bid = float(target)
    if bid > cap:
        bid = cap

    # Also keep a floor so we don't get outbid by Alex/David/Eric.
    floor = min(budget, DAILY_SALARY * 0.50)
    if bid < floor:
        bid = floor

    # If budget is extremely low, just spend what we can.
    if budget <= 0:
        return 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
