    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return 1.0

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(avg_prev * 1.1, 90.0))
    else:
        bid = min(my_status['budget'], avg_prev * 1.02)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY * 0.85:
            if hp > 3:
                base_bid = DAILY_SALARY * 0.35
            else:
                base_bid = DAILY_SALARY * 0.9
        else:
            base_bid = max(DAILY_SALARY * 0.5, max_prev + 2.0)
    else:
        if hp <= 2:
            base_bid = DAILY_SALARY * 0.85
        else:
            base_bid = DAILY_SALARY * 0.55
    supply_int = int(supply)
    num_units = supply_int // WATER_REQ
    if num_units >= len(alive_opponents) + 1:
        base_bid *= 0.8
    elif num_units <= 1:
        base_bid *= 1.2
    bid = max(1.0, min(budget, base_bid))
    return bid
